        import pulumi_juniper_mist as junipermist

        networktemplate_one = junipermist.site.Networktemplate("networktemplate_one",
            site_id=terraform_test["id"],
            dns_servers=[
                "8.8.8.8",
                "1.1.1.1",
            ],
            dns_suffixes=["mycorp.com"],
            ntp_servers=["pool.ntp.org"],
            additional_config_cmds=[
                "set system hostname test",
                "set system services ssh root-login allow",
            ],
            networks={
                "network_one": {
                    "vlan_id": "10",
                },
                "network_two": {
                    "vlan_id": "11",
                },
            },
            port_usages={
                "trunk": {
                    "all_networks": True,
                    "enable_qos": True,
                    "mode": "port_usage_one",
                    "port_network": "network_one",
                },
            },
            radius_config={
                "acct_interim_interval": 60,
                "coa_enabled": True,
                "network": "network_one",
                "acct_servers": [{
                    "host": "1.2.3.4",
                    "secret": "secret",
                }],
                "auth_servers": [{
                    "host": "1.2.3.4",
                    "secret": "secret",
                }],
            },
            switch_matching={
                "enable": True,
                "rules": [{
                    "name": "switch_rule_one",
                    "match_name": "corp",
                    "match_name_offset": 3,
                    "match_role": "core",
                    "port_config": {
                        "ge-0/0/0-10": {
                            "usage": "port_usage_one",
                        },
                    },
                }],
            })
